# =============================================================================
# Stage 6: Control Horizon & Distant-Forecast Discounting
# =============================================================================
"""Control horizon and value of distant, uncertain forecasts.

The provided market observations are unchanged. Discounting affects only the
planning objective after the three published hours, not the scoring formula.
"""

_PreviousCandidateAgent = BatteryAgent


class BatteryAgent(_PreviousCandidateAgent):
    """Configure planning horizon, terminal SoC valuation, and future noise scaling."""

    FORECAST_DISCOUNT_HOURS: ClassVar[float] = 0.0
    FUTURE_NOISE_SCALE: ClassVar[float] = 1.0

    def _future_sigma(self, lead: int) -> float:
        """Scale future hourly error standard deviation by `FUTURE_NOISE_SCALE`."""
        return super()._future_sigma(lead) * self.FUTURE_NOISE_SCALE

    def _choose_action(
        self,
        energy: float,
        weights: FloatArray,
        demand: FloatArray,
        terminal_value: float,
    ) -> float:
        """Optionally discount stage weights beyond the 3 known market hours."""
        if self.FORECAST_DISCOUNT_HOURS > 0:
            uncertain_lead = np.maximum(np.arange(len(weights)) - 2, 0.0)
            discount = np.exp(-uncertain_lead / self.FORECAST_DISCOUNT_HOURS)
            weights = weights * discount
            terminal_value *= float(discount[-1])
        return super()._choose_action(energy, weights, demand, terminal_value)


BatteryAgent.HORIZON = 18
BatteryAgent.TERMINAL_FACTOR = 0.9
BatteryAgent.FUTURE_NOISE_SCALE = 1.0


# =============================================================================
# Stage 7: Causal Short-Horizon CatBoost Multi-Quantile Demand Model
# =============================================================================
"""Causal short-horizon demand prediction and conditional current-demand scenarios."""


def demand_block_remaining(agent: BatteryAgent, obs: ObservationDict) -> int:
    """Return the number of hours remaining in the current 7-day evaluation window."""
    stamp = obs["timestamp"]
    if isinstance(stamp, str):
        stamp = datetime.fromisoformat(stamp.replace("Z", "+00:00"))
    following = (stamp.replace(day=28) + timedelta(days=4)).replace(day=1)
    end = (
        (following - timedelta(days=1)).day
        if agent.EVALUATION_WEEK_START is None
        else agent.EVALUATION_WEEK_START + 6
    )
    if not end - 6 <= stamp.day <= end:
        return 100000
    return (end - stamp.day) * 24 + 24 - stamp.hour


def demand_features(
    agent: BatteryAgent,
    obs: ObservationDict,
    prediction: FloatArray,
    scenarios: FloatArray,
) -> FloatArray:
    """Build the 82-column causal feature matrix for short-horizon GBDT demand models.

    Generates one row per lead hour `0..min(6, len(prediction)-1)` combining lead-specific
    predictions, profile baselines, harmonic calendar waves, lagged telemetry (1, 2, 3, 6,
    12, 24h), rolling net load statistics (3, 6, 24h), latest 5-minute sensor readings,
    and the 3 published market prices and CO2 intensities.
    """
    count = min(7, len(prediction))
    lead = np.arange(count)
    stamp = obs["timestamp"]
    if isinstance(stamp, str):
        stamp = datetime.fromisoformat(stamp.replace("Z", "+00:00"))
    hour = int(obs["hour"])
    phase = (hour + lead) * np.pi / 12
    profile = agent._profile_baseline(obs, lead)
    net = (prediction[:count, 0] - prediction[:count, 1]) / 1000.0
    anchor = net.copy()
    anchor[0] = float(np.mean(scenarios)) / 1000.0
    weekend = ((int(obs["day_of_week"]) + (hour + lead) // 24) % 7 >= 5).astype(float)
    holiday = np.array(
        [float(agent._low_activity(stamp + timedelta(hours=int(h)))) for h in lead]
    )
    columns: list[npt.ArrayLike] = [
        lead / 6,
        net,
        anchor,
        profile[:, 0],
        profile[:, 1],
        weekend,
        holiday,
        np.sin(phase),
        np.cos(phase),
        np.sin(2 * phase),
        np.cos(2 * phase),
        prediction[:count, 2] / 0.15,
        prediction[:count, 3] / 0.1,
    ]
    assert agent.previous_key is not None
    key = agent.previous_key
    history = np.array(
        [agent.history.get(key + h, np.full(6, np.nan)) for h in range(-24, 0)]
    )
    fixed: list[float] = [
        float(np.sin(stamp.timetuple().tm_yday * 2 * np.pi / 365.25)),
        float(np.cos(stamp.timetuple().tm_yday * 2 * np.pi / 365.25)),
        float(agent.conditional_continuous),
        min(agent.observed_steps, 48) / 48,
    ]
    for lag in (1, 2, 3, 6, 12, 24):
        row = history[24 - lag]
        fixed.extend(np.nan_to_num(row[[0, 1, 4, 5]], nan=0.0))
        fixed.extend(np.isfinite(row[[0, 1, 4, 5]]).astype(float))
        fixed.append(float(row[0] - row[1]) if np.isfinite(row[:2]).all() else 0.0)
    for width in (3, 6, 24):
        values = history[-width:, :2]
        valid = np.isfinite(values).all(axis=1)
        diff = values[valid, 0] - values[valid, 1]
        fixed.extend([
            float(np.mean(diff)) if len(diff) else 0.0,
            float(np.std(diff)) if len(diff) else 0.0,
            float(np.mean(valid)),
        ])
    telemetry = obs["noves_dades_5min"]
    fixed.extend([
        telemetry["ultim_consum_kw"] / 1000,
        telemetry["ultima_solar_kw"] / 1000,
        telemetry.get("irradiancia_wm2", 0) / 1000,
        telemetry.get("temp_ambient_c", 20) / 25,
    ])
    for field, scale in [("preus_properes_24h", 0.15), ("co2_properes_24h", 0.1)]:
        known = np.asarray(obs[field], dtype=float)[:3] / scale
        fixed.extend(np.pad(known, (0, 3 - len(known)), mode="edge"))
    columns.extend(np.full(count, v) for v in fixed)
    return np.nan_to_num(np.column_stack(columns), nan=0.0, posinf=0.0, neginf=0.0)


def cat_demand_predict(x: npt.ArrayLike, model: CatBoostModelTuple) -> FloatArray:
    """Evaluate an oblivious-tree CatBoost multi-output ensemble using pure NumPy."""
    features, borders, leaves, scale, bias = model
    x_arr = np.asarray(x, dtype=np.float32)
    result = np.empty((len(x_arr), len(bias)))
    tree = np.arange(len(features))[:, None]
    for start in range(0, len(x_arr), 256):
        batch = x_arr[start : start + 256]
        index = np.zeros((len(features), len(batch)), dtype=int)
        for depth in range(features.shape[1]):
            index += (
                batch[:, features[:, depth]].T > borders[:, depth, None]
            ).astype(int) * (1 << depth)
        result[start : start + len(batch)] = (
            np.sum(leaves[tree, index], axis=0) * scale + bias
        )
    return result


def apply_demand_output(
    agent: BatteryAgent,
    prediction: FloatArray,
    output: FloatArray | None,
    eligible: bool,
) -> FloatArray:
    """Integrate CatBoost quantile predictions into net demand forecasts and sigmas."""
    raw_net = prediction[:, 0] - prediction[:, 1]
    original = agent.net_original_scenarios
    agent.net_current_scenarios = original.copy()
    agent.net_sigma = None
    if output is None or not eligible:
        return prediction
    n = min(len(output), len(prediction), agent.net_remaining, agent.NET_MAX_LEAD + 1)
    anchor = raw_net[:n].copy()
    anchor[0] = float(np.mean(original))
    if agent.NET_TARGET == "components":
        expected = np.maximum(output[:n, 0], 0) - np.maximum(output[:n, 1], 0)
        correction = expected * 1000 - anchor
        quantiles: FloatArray | None = None
    elif agent.NET_TARGET == "absolute":
        quantiles = np.sort(output[:n], axis=1) * 1000
        correction = np.median(quantiles, axis=1) - anchor
    else:
        quantiles = np.sort(output[:n], axis=1) * 1000 + anchor[:, None]
        correction = np.median(quantiles, axis=1) - anchor
    correction = np.clip(correction, -agent.NET_CLIP, agent.NET_CLIP)
    if quantiles is not None and output.shape[1] > 2 and agent.NET_CDF_BLEND > 0:
        probabilities = (np.arange(len(original)) + 0.5) / len(original)
        q = np.interp(probabilities, agent.NET_QUANTILES, quantiles[0])
        mean = float(np.mean(q))
        anchor_mean = float(np.mean(original))
        q = (
            anchor_mean
            + agent.NET_Q_CENTER * (mean - anchor_mean)
            + agent.NET_Q_SPREAD * (q - mean)
        )
        agent.net_current_scenarios = (
            (1 - agent.NET_CDF_BLEND) * original + agent.NET_CDF_BLEND * q
        )
    else:
        agent.net_current_scenarios = original + agent.NET_CURRENT_GAIN * correction[0]
    updated = raw_net.copy()
    updated[0] += float(np.mean(agent.net_current_scenarios) - np.mean(original))
    if n > 1:
        fade = (
            np.exp(-np.arange(n - 1) / agent.NET_FUTURE_DECAY)
            if agent.NET_FUTURE_DECAY > 0
            else np.ones(n - 1)
        )
        updated[1:n] += agent.NET_FUTURE_GAIN * correction[1:n] * fade
    prediction[:, 0], prediction[:, 1] = np.maximum(updated, 0), np.maximum(-updated, 0)
    if quantiles is not None and output.shape[1] > 2:
        sigma = np.array([
            (
                np.interp(0.84, agent.NET_QUANTILES, q)
                - np.interp(0.16, agent.NET_QUANTILES, q)
            )
            / 2
            for q in quantiles
        ])
        agent.net_sigma = np.maximum(sigma, 5.0)
    return prediction


_BeforeDemandModel = BatteryAgent


class BatteryAgent(_BeforeDemandModel):
    """Augment causal forecasts with short-horizon CatBoost quantile predictions."""

    NET_MODEL: ClassVar[CatBoostModelTuple | None] = None
    NET_TARGET: ClassVar[str] = "residual"
    NET_CURRENT_GAIN: ClassVar[float] = 0.0
    NET_FUTURE_GAIN: ClassVar[float] = 0.0
    NET_CDF_BLEND: ClassVar[float] = 0.0
    NET_Q_CENTER: ClassVar[float] = 1.0
    NET_Q_SPREAD: ClassVar[float] = 1.0
    NET_SIGMA_BLEND: ClassVar[float] = 0.0
    NET_MAX_LEAD: ClassVar[int] = 6
    NET_CLIP: ClassVar[float] = 400.0
    NET_FUTURE_DECAY: ClassVar[float] = 0.0
    NET_PRICE_MULTIPLIER: ClassVar[float] = 1.0
    NET_QUANTILES: ClassVar[FloatArray] = np.array(
        [0.05, 0.15, 0.25, 0.35, 0.5, 0.65, 0.75, 0.85, 0.95]
    )

    def _forecast(self, obs: ObservationDict, *args: Any) -> FloatArray:
        """Evaluate `NET_MODEL` quantiles and store horizon-specific uncertainty `net_sigma`."""
        prediction = super()._forecast(obs, *args)
        price_scale = self.normalization[1] / max(self.normalization[0], 1.0)
        self.net_price_weights: FloatArray = 0.3 * prediction[:, 2] / max(price_scale, 1e-6)
        self.net_known_count: int = min(len(args[0]), 3)
        self.net_original_scenarios: FloatArray = super()._current_net_scenarios(
            float(prediction[0, 0] - prediction[0, 1])
        )
        self.net_current_scenarios: FloatArray = self.net_original_scenarios.copy()
        self.net_sigma: FloatArray | None = None
        self.net_remaining: int = demand_block_remaining(self, obs)
        if self.NET_MODEL is None:
            return prediction
        eligible = self.observed_steps > 1 and self.conditional_continuous
        if not eligible:
            return prediction
        output = cat_demand_predict(
            demand_features(self, obs, prediction, self.net_original_scenarios),
            self.NET_MODEL,
        )
        return apply_demand_output(self, prediction, output, eligible)

    def _current_net_scenarios(self, forecast: float) -> FloatArray:
        """Return the cached current-hour net demand scenarios updated during `_forecast`."""
        return self.net_current_scenarios

    def _choose_action(
        self,
        energy: float,
        weights: FloatArray,
        demand: FloatArray,
        terminal: float,
    ) -> float:
        """Adjust relative price weight multiplier before invoking the action optimizer."""
        if self.NET_PRICE_MULTIPLIER != 1.0:
            weights = weights + (self.NET_PRICE_MULTIPLIER - 1.0) * self.net_price_weights
            terminal = (
                self.TERMINAL_FACTOR * max(0.0, float(np.mean(weights))) * self.eta
                if self.net_known_count == 3
                else 0.0
            )
        return super()._choose_action(energy, weights, demand, terminal)

    def _future_sigma(self, lead: int) -> float:
        """Blend baseline lead-time sigma with CatBoost inter-quantile spread `net_sigma`."""
        original = super()._future_sigma(lead)
        if (
            self.NET_SIGMA_BLEND
            and self.net_sigma is not None
            and lead < len(self.net_sigma)
        ):
            return float(
                (1 - self.NET_SIGMA_BLEND) * original
                + self.NET_SIGMA_BLEND * self.net_sigma[lead]
            )
        return original


# =============================================================================
# Stage 8: Night Persistence Expert
# =============================================================================
"""Night persistence expert, calibrated only on fitting-week errors."""

NIGHT_ERROR_QUANTILES: FloatArray = np.zeros((7, 21))


def apply_night_expert(
    agent: BatteryAgent,
    prediction: FloatArray,
    last_solar: float,
) -> FloatArray:
    """Override night-time current-hour scenarios using persistence error quantiles."""
    lead = np.arange(len(prediction))
    future_hour = (agent.current_hour + lead) % 24
    current_night = agent.current_hour <= 5 or agent.current_hour == 23
    available = agent.conditional_continuous or agent.observed_steps == 1
    agent.night_mask = (
        ((future_hour <= 5) | (future_hour == 23))
        & (lead <= 6)
        & (lead < agent.net_remaining)
    )
    agent.night_mask &= bool(current_night and available and last_solar < 1.0)
    if not agent.night_mask.any():
        return prediction
    if (
        agent.NIGHT_CURRENT_BLEND == 0
        and agent.NIGHT_FUTURE_GAIN == 0
        and agent.NIGHT_SIGMA_BLEND == 0
    ):
        return prediction
    assert agent.conditional_previous_net is not None
    last = agent.conditional_previous_net
    net = prediction[:, 0] - prediction[:, 1]
    if (
        agent.NIGHT_CURRENT_BLEND
        and agent.observed_steps > 1
        and agent.conditional_continuous
    ):
        original = agent.net_current_scenarios
        errors = NIGHT_ERROR_QUANTILES[0]
        center = float(np.mean(errors))
        sigma = max(float(np.std(errors)), 1e-6)
        errors = center + (errors - center) * max(1.0, agent.NIGHT_STD_FLOOR / sigma)
        q = np.interp(
            (np.arange(len(original)) + 0.5) / len(original),
            (np.arange(21) + 0.5) / 21,
            last + errors,
        )
        updated = (
            (1 - agent.NIGHT_CURRENT_BLEND) * original + agent.NIGHT_CURRENT_BLEND * q
        )
        net[0] += float(np.mean(updated) - np.mean(original))
        agent.net_current_scenarios = updated
    for h in np.flatnonzero(agent.night_mask & (lead > 0)):
        expected = last + float(np.median(NIGHT_ERROR_QUANTILES[h]))
        net[h] = (1 - agent.NIGHT_FUTURE_GAIN) * net[h] + agent.NIGHT_FUTURE_GAIN * expected
    prediction[:, 0], prediction[:, 1] = np.maximum(net, 0), np.maximum(-net, 0)
    return prediction


_BeforeNightExpert = BatteryAgent


class BatteryAgent(_BeforeNightExpert):
    """Apply specialized night-time persistence scenarios and uncertainty between 23:00 and 05:00."""

    NIGHT_CURRENT_BLEND: ClassVar[float] = 0.0
    NIGHT_FUTURE_GAIN: ClassVar[float] = 0.0
    NIGHT_SIGMA_BLEND: ClassVar[float] = 0.0
    NIGHT_STD_FLOOR: ClassVar[float] = 5.0

    def _forecast(self, obs: ObservationDict, *args: Any) -> FloatArray:
        """Apply night persistence expert after the short-horizon CatBoost forecast."""
        prediction = super()._forecast(obs, *args)
        return apply_night_expert(
            self, prediction, float(obs["noves_dades_5min"]["ultima_solar_kw"])
        )

    def _future_sigma(self, lead: int) -> float:
        """Use empirical night-persistence error standard deviation during masked night hours."""
        old = super()._future_sigma(lead)
        if (
            self.NIGHT_SIGMA_BLEND
            and lead < len(self.night_mask)
            and self.night_mask[lead]
        ):
            sigma = max(float(np.std(NIGHT_ERROR_QUANTILES[lead])), self.NIGHT_STD_FLOOR)
            return float((1 - self.NIGHT_SIGMA_BLEND) * old + self.NIGHT_SIGMA_BLEND * sigma)
        return old

