# =============================================================================
# Stage 9: Cost-Constrained Receding-Horizon Pareto Controller
# =============================================================================
"""Cost-constrained receding-horizon alternatives to the frozen demand agent.

Forecast guards are estimates, not guarantees of realized savings.
"""

_BeforeParetoControl = BatteryAgent


class BatteryAgent(_BeforeParetoControl):
    """Receding-horizon controller with configurable Pareto gating and correlated error scaling."""

    CTRL_HORIZON: ClassVar[int] = 18
    CTRL_TERMINAL: ClassVar[float] = 0.9
    CTRL_PRICE: ClassVar[float] = 1.01
    CTRL_DISCOUNT: ClassVar[float] = 0.0
    CTRL_SIGMA_NEAR: ClassVar[float] = 1.0
    CTRL_SIGMA_FAR: ClassVar[float] = 1.0
    CTRL_CURRENT_SPREAD: ClassVar[float] = 1.0
    CTRL_CORRELATED_SCALE: ClassVar[float] = 1.0
    CTRL_GATE: ClassVar[int] = 0
    CTRL_GATE_BLEND: ClassVar[float] = 1.0
    CTRL_GATE_REGIME: ClassVar[str] = "all"
    CTRL_CYCLE_PENALTY: ClassVar[float] = 0.0

    def _future_sigma(self, lead: int) -> float:
        """Apply near-horizon (`lead <= 6`) vs. far-horizon sigma multipliers."""
        sigma = super()._future_sigma(lead)
        return sigma * (self.CTRL_SIGMA_NEAR if lead <= 6 else self.CTRL_SIGMA_FAR)

    def _current_net_scenarios(self, forecast: float) -> FloatArray:
        """Scale current-hour net demand scenario dispersion around its mean."""
        scenarios = super()._current_net_scenarios(forecast)
        mean = float(np.mean(scenarios))
        return mean + self.CTRL_CURRENT_SPREAD * (scenarios - mean)

    def _future_value(
        self,
        weights: FloatArray,
        demand: FloatArray,
        terminal: float,
    ) -> tuple[FloatArray, FloatArray]:
        """Temporarily scale `FUTURE_COMPONENT_SCALE` by `CTRL_CORRELATED_SCALE` during DP."""
        original = self.FUTURE_COMPONENT_SCALE
        self.FUTURE_COMPONENT_SCALE = original * self.CTRL_CORRELATED_SCALE
        try:
            return super()._future_value(weights, demand, terminal)
        finally:
            self.FUTURE_COMPONENT_SCALE = original

    def _choose_action(
        self,
        energy: float,
        weights: FloatArray,
        demand: FloatArray,
        terminal: float,
    ) -> float:
        """Optimize battery action with optional cycle penalty or price/carbon Pareto gating."""
        count = min(len(weights), self.CTRL_HORIZON)
        price = self.net_price_weights[:count].copy()
        carbon = weights[:count] - price
        price *= self.CTRL_PRICE
        weights = carbon + price
        demand = demand[:count]
        if self.CTRL_DISCOUNT:
            discount = np.exp(-np.maximum(np.arange(count) - 2, 0) / self.CTRL_DISCOUNT)
            weights *= discount
            price *= discount
            carbon *= discount
        known_end = self.net_known_count < 3
        terminal = (
            0.0
            if known_end
            else self.CTRL_TERMINAL * max(0.0, float(weights.mean())) * self.eta
        )
        if not self.CTRL_GATE and not self.CTRL_CYCLE_PENALTY:
            return _BeforeDemandModel._choose_action(
                self, energy, weights, demand, terminal
            )
        # Nonconvex negative-price cases retain the inherited grid-search fallback solver.
        if (weights < 0).any() or (price < 0).any() or (carbon < 0).any():
            return _BeforeDemandModel._choose_action(
                self, energy, weights, demand, terminal
            )
        combined_k, combined_v = self._future_value(weights[1:], demand[1:], terminal)
        scenarios = self._current_net_scenarios(float(demand[0]))
        low = -max(0.0, min(self.power, energy * self.eta - 1e-4))
        high = max(0.0, min(self.power, (self.capacity - energy) / self.eta - 1e-4))

        def powers(knots: FloatArray) -> FloatArray:
            change = knots - energy
            return np.where(change >= 0, change / self.eta, change * self.eta)

        actions = np.unique(
            np.clip(np.r_[0.0, low, high, -scenarios, powers(combined_k)], low, high)
        )

        def evaluate(
            act_grid: FloatArray,
            knots: FloatArray,
            values: FloatArray,
            weight: float,
        ) -> FloatArray:
            following = energy + np.where(
                act_grid >= 0, act_grid * self.eta, act_grid / self.eta
            )
            imported = np.mean(np.maximum(act_grid[:, None] + scenarios, 0.0), axis=1)
            return weight * imported + np.interp(following, knots, values)

        joint = evaluate(actions, combined_k, combined_v, float(weights[0]))
        baseline = float(actions[np.argmin(joint + 1e-8 * np.abs(actions))])
        if self.CTRL_CYCLE_PENALTY:
            penalty = self.CTRL_CYCLE_PENALTY * max(float(weights.mean()), 0.0)
            return float(actions[np.argmin(joint + (penalty + 1e-8) * np.abs(actions))])
        active = (
            self.CTRL_GATE_REGIME == "all"
            or (self.CTRL_GATE_REGIME == "solar" and 7 <= self.current_hour <= 18)
            or (
                self.CTRL_GATE_REGIME == "night"
                and (self.current_hour <= 5 or self.current_hour >= 23)
            )
        )
        if not active:
            return baseline
        pt = (
            0.0
            if known_end
            else self.CTRL_TERMINAL * max(0.0, float(price.mean())) * self.eta
        )
        ct = (
            0.0
            if known_end
            else self.CTRL_TERMINAL * max(0.0, float(carbon.mean())) * self.eta
        )
        pk, pv = self._future_value(price[1:], demand[1:], pt)
        ck, cv = self._future_value(carbon[1:], demand[1:], ct)
        actions = np.unique(
            np.clip(np.r_[actions, powers(pk), powers(ck), baseline], low, high)
        )
        pc = evaluate(actions, pk, pv, float(price[0]))
        cc = evaluate(actions, ck, cv, float(carbon[0]))
        jc = evaluate(actions, combined_k, combined_v, float(weights[0]))
        b = int(np.argmin(abs(actions - baseline)))
        valid = (pc <= pc[b] + 1e-8) & (cc <= cc[b] + 1e-8)
        if self.CTRL_GATE == 2:
            valid &= jc <= jc[b] + 1e-8
        candidate = float(
            actions[np.argmin(np.where(valid, cc + 1e-8 * np.abs(actions - baseline), np.inf))]
        )
        return float(baseline + self.CTRL_GATE_BLEND * (candidate - baseline))


# =============================================================================
# Stage 10: Focused Daytime Current-Demand CatBoost Distribution
# =============================================================================
"""A separate CatBoost distribution for current net demand; future model stays fixed."""


def score_current_distribution(agent: BatteryAgent, output: FloatArray | None) -> None:
    """Blend focused daytime CatBoost quantile predictions into `net_current_scenarios`."""
    if output is None or agent.observed_steps <= 1 or not agent.conditional_continuous:
        return
    if agent.night_mask[0]:
        return
    old = agent.net_current_scenarios
    q = np.sort(np.asarray(output).reshape(-1)) * 1000.0
    if agent.SCORE_CURRENT_TARGET == "residual":
        q += float(np.mean(agent.net_original_scenarios))
    proposed = np.interp((np.arange(len(old)) + 0.5) / len(old), agent.NET_QUANTILES, q)
    proposed = old + np.clip(proposed - old, -300.0, 300.0)
    agent.net_current_scenarios = (
        (1 - agent.SCORE_CURRENT_BLEND) * old + agent.SCORE_CURRENT_BLEND * proposed
    )


_BeforeScoreCurrent = BatteryAgent


class BatteryAgent(_BeforeScoreCurrent):
    """Refine daytime current-hour demand distribution using `SCORE_CURRENT_MODEL`."""

    SCORE_CURRENT_MODEL: ClassVar[CatBoostModelTuple | None] = None
    SCORE_CURRENT_BLEND: ClassVar[float] = 0.0
    SCORE_CURRENT_TARGET: ClassVar[str] = "absolute"

    def _forecast(self, obs: ObservationDict, *args: Any) -> FloatArray:
        """Cache `ensemble_features` and apply `SCORE_CURRENT_MODEL` during daytime hours."""
        prediction = super()._forecast(obs, *args)
        self.ensemble_features: FloatArray = demand_features(
            self, obs, prediction, self.net_original_scenarios
        )
        if self.SCORE_CURRENT_MODEL is None or self.SCORE_CURRENT_BLEND == 0:
            return prediction
        if (
            self.observed_steps <= 1
            or not self.conditional_continuous
            or self.night_mask[0]
        ):
            return prediction
        x = focus_features(self, obs, prediction)
        output = cat_demand_predict(x, self.SCORE_CURRENT_MODEL)[0]
        mean = float(np.mean(self.net_current_scenarios))
        score_current_distribution(self, output)
        net = (
            prediction[0, 0]
            - prediction[0, 1]
            + float(np.mean(self.net_current_scenarios))
            - mean
        )
        prediction[0, 0], prediction[0, 1] = max(net, 0.0), max(-net, 0.0)
        return prediction

