"""Causal contrasts for daytime and decision-weighted demand forecasting."""


def focus_expand(x: npt.ArrayLike, spreads: npt.ArrayLike) -> FloatArray:
    """Append 18 engineered causal contrast and ramp features to the 82 base demand features.

    Note: The original 82 feature columns are preserved in indices `0..81`, so models
    trained on the base feature space can also be evaluated on the 100-column matrix.
    """
    x_arr = np.asarray(x, dtype=float)
    differences = [
        x_arr[:, 25] - x_arr[:, 2],
        x_arr[:, 25] - x_arr[:, 34],
        x_arr[:, 34] - x_arr[:, 43],
        x_arr[:, 25] - 2 * x_arr[:, 34] + x_arr[:, 43],
        x_arr[:, 17] - x_arr[:, 26],
        x_arr[:, 18] - x_arr[:, 27],
        x_arr[:, 17] - x_arr[:, 3],
        x_arr[:, 18] - x_arr[:, 4],
        x_arr[:, 25] - x_arr[:, 70],
        x_arr[:, 2] - x_arr[:, 71],
        x_arr[:, 2] - x_arr[:, 74],
        x_arr[:, 2] - x_arr[:, 77],
        np.abs(x_arr[:, 25] - x_arr[:, 34]),
        np.maximum(-x_arr[:, 2], 0),
        np.maximum(x_arr[:, 2], 0),
        x_arr[:, 5] * x_arr[:, 7],
        x_arr[:, 6] * x_arr[:, 7],
        np.asarray(spreads) / 1000.0,
    ]
    return np.column_stack([x_arr, *differences])


def focus_features(
    agent: BatteryAgent,
    obs: ObservationDict,
    prediction: FloatArray,
) -> FloatArray:
    """Compute the 100-column expanded feature row for current-hour demand inference."""
    x = demand_features(agent, obs, prediction, agent.net_original_scenarios)[:1]
    return focus_expand(x, [float(np.std(agent.net_original_scenarios))])

