# =============================================================================
# Stage 11: Three-Family GBDT Quantile Ensemble (CatBoost + LightGBM + XGBoost)
# =============================================================================
"""LightGBM numerical-tree inference; NumPy is the only runtime dependency."""


def lgb_predict(x: npt.ArrayLike, forest: LightGBMForestTuple) -> FloatArray:
    """Evaluate a LightGBM numerical decision-tree forest using pure NumPy.

    Parameters
    ----------
    x : npt.ArrayLike
        2D feature matrix of shape ``(n_samples, n_features)``.
    forest : LightGBMForestTuple
        Tuple ``(feature, threshold, left, right, value, default_left, missing_type, divisor)``
        where leaf nodes are encoded with ``feature == -1`` and leaf values include
        shrinkage and base margin.
    """
    feature, threshold, left, right, value, default_left, missing_type, divisor = forest
    x_arr = np.asarray(x, dtype=np.float64)
    if x_arr.ndim != 2:
        raise ValueError("Expected 2D features.")
    result = np.empty(len(x_arr), dtype=float)
    tree_ids = np.arange(len(feature))[:, None]
    for start in range(0, len(x_arr), 256):
        batch = x_arr[start : start + 256]
        row = np.arange(len(batch))[None, :]
        node = np.zeros((len(feature), len(batch)), dtype=np.int32)
        for _ in range(feature.shape[1]):
            f = feature[tree_ids, node]
            active = f >= 0
            if not active.any():
                break
            values = batch[row, np.maximum(f, 0)]
            missing = missing_type[tree_ids, node]
            values = np.where(np.isnan(values) & (missing != 1), 0.0, values)
            is_missing = ((missing == 1) & np.isnan(values)) | (
                (missing == 2) & (np.abs(values) <= float(np.float32(1e-35)))
            )
            go_left = np.where(
                is_missing, default_left[tree_ids, node], values <= threshold[tree_ids, node]
            )
            following = np.where(go_left, left[tree_ids, node], right[tree_ids, node])
            node = np.where(active, following, node)
        result[start : start + len(batch)] = np.sum(value[tree_ids, node], axis=0) / divisor
    return result


"""Three real GBDT forecast families feeding the joint-score convex planner."""


def xgb_quantile_predict(x: npt.ArrayLike, forest: XGBoostForestTuple) -> FloatArray:
    """Evaluate an XGBoost decision-tree forest using pure NumPy."""
    feature, threshold, left, right, value = forest
    x_arr = np.asarray(x, dtype=np.float32)
    result = np.empty(len(x_arr))
    tree = np.arange(len(feature))[:, None]
    for start in range(0, len(x_arr), 256):
        batch = x_arr[start : start + 256]
        rows = np.arange(len(batch))[None, :]
        node = np.zeros((len(feature), len(batch)), dtype=int)
        for _ in range(feature.shape[1]):
            f = feature[tree, node]
            active = f >= 0
            if not active.any():
                break
            go = batch[rows, np.maximum(f, 0)] < threshold[tree, node]
            node = np.where(active, np.where(go, left[tree, node], right[tree, node]), node)
        result[start : start + len(batch)] = np.sum(value[tree, node], axis=0)
    return result


def ensemble_predict(
    x: npt.ArrayLike,
    models: EnsembleModelsTuple,
    weights: FloatArray,
) -> FloatArray:
    """Compute weighted multi-quantile predictions across CatBoost, LightGBM, and XGBoost."""
    cat, lgb, xgb = models
    a = cat_demand_predict(x, cat)
    b = np.column_stack([lgb_predict(x, m) for m in lgb])
    c = np.column_stack([xgb_quantile_predict(x, m) for m in xgb])
    return np.sort(weights[0] * a + weights[1] * b + weights[2] * c, axis=1)


def ensemble_apply(
    agent: BatteryAgent,
    demand: FloatArray,
    output: FloatArray | None,
) -> FloatArray:
    """Apply GBDT ensemble quantile predictions to net demand and future uncertainty."""
    if output is None or agent.observed_steps <= 1 or not agent.conditional_continuous:
        return demand
    n = min(len(output), len(demand), agent.net_remaining, 7)
    quantiles = np.sort(output[:n], axis=1) * 1000.0
    if not agent.night_mask[0] and agent.ENSEMBLE_CURRENT:
        old = agent.net_current_scenarios
        q = np.interp(
            (np.arange(len(old)) + 0.5) / len(old), agent.ENSEMBLE_ALPHAS, quantiles[0]
        )
        new = old + agent.ENSEMBLE_CURRENT * np.clip(q - old, -300.0, 300.0)
        demand[0] += float(np.mean(new) - np.mean(old))
        agent.net_current_scenarios = new
    for h in range(1, n):
        if agent.night_mask[h]:
            continue
        median = float(np.interp(0.5, agent.ENSEMBLE_ALPHAS, quantiles[h]))
        demand[h] += (
            agent.ENSEMBLE_FUTURE
            * np.clip(median - demand[h], -400.0, 400.0)
            * np.exp(-(h - 1) / 6)
        )
        if agent.net_sigma is not None and h < len(agent.net_sigma):
            sigma = max(
                5.0,
                float(
                    (
                        np.interp(0.84, agent.ENSEMBLE_ALPHAS, quantiles[h])
                        - np.interp(0.16, agent.ENSEMBLE_ALPHAS, quantiles[h])
                    )
                    / 2
                ),
            )
            agent.net_sigma[h] = (
                (1 - agent.ENSEMBLE_SIGMA) * agent.net_sigma[h]
                + agent.ENSEMBLE_SIGMA * sigma
            )
    return demand


_BeforeGBDTEnsemble = BatteryAgent


class BatteryAgent(_BeforeGBDTEnsemble):
    """Final competition agent combining the 3-family GBDT quantile ensemble with convex DP."""

    CTRL_GATE: ClassVar[int] = 0
    CTRL_PRICE: ClassVar[float] = 1.0
    CTRL_CYCLE_PENALTY: ClassVar[float] = 0.0
    ENSEMBLE_MODELS: ClassVar[EnsembleModelsTuple | None] = None
    ENSEMBLE_WEIGHTS: ClassVar[FloatArray] = np.array([1 / 3, 1 / 3, 1 / 3])
    ENSEMBLE_ALPHAS: ClassVar[FloatArray] = np.array([0.1, 0.25, 0.5, 0.75, 0.9])
    ENSEMBLE_CURRENT: ClassVar[float] = 0.0
    ENSEMBLE_FUTURE: ClassVar[float] = 0.0
    ENSEMBLE_SIGMA: ClassVar[float] = 0.0

    def _forecast(self, obs: ObservationDict, *args: Any) -> FloatArray:
        """Evaluate the 3-family GBDT quantile ensemble and update short-horizon uncertainty."""
        p = super()._forecast(obs, *args)
        if self.ENSEMBLE_MODELS is None:
            return p
        if self.observed_steps <= 1 or not self.conditional_continuous:
            return p
        x = focus_expand(
            self.ensemble_features,
            np.full(
                len(self.ensemble_features),
                float(np.std(self.net_original_scenarios)),
            ),
        )
        output = ensemble_predict(x, self.ENSEMBLE_MODELS, self.ENSEMBLE_WEIGHTS)
        net = ensemble_apply(self, (p[:, 0] - p[:, 1]).copy(), output)
        p[:, 0], p[:, 1] = np.maximum(net, 0.0), np.maximum(-net, 0.0)
        return p

